cases.input:
a -> b
layers: {alternative: {c -> d}}
scenarios: {x: {a -> c}}
steps: {first: {b -> c}; second: {c -> d}}

vars: {name: Outer}
classes: {service: {shape: diamond; style.fill: "#ffeecc"}}
cluster: Cluster {
  vars: {name: Inner}
  a: ${name}
  b: B
  *.class: service
  a -> *: call
}
outside: ${name}

direction: right
service: Service {
  api: API
  cache: Cache {shape: cylinder}
  api -> cache: lookup
}
client: Client
client -> service.api: request
service.api -> client: response
service.api -> service.cache: refresh

a: A
"a.b": Dotted {
  "x.y": Leaf
  inner: {z}
}
a -> "a.b"."x.y"
"a.b".inner.z -> "a.b"."x.y"

classes: {service: {style.fill: "#ffcc00"}}
a: A {class: service; style.stroke: "#003366"}
b: B {shape: diamond}
a -> b: request {style.stroke-dash: 3}

users: {shape: sql_table; id: int {constraint: primary_key}; name: text}
posts: {shape: sql_table; user_id: int}
posts.user_id -> users.id

digraph Ranking {
  node [shape=box];
  {rank=same; a; b;}
  a -> b;
}

digraph Compass {
  node [shape=box];
  a:ne -> b:c;
}

digraph Appearance {
  rankdir=RL;
  node [shape=box];
  a [shape=cylinder,image="https://import.invalid/logo.svg"];
  a -> b [color="#ff0000",style=bold];
}

digraph Pipeline {
  rankdir=LR;
  node [shape=box];
  subgraph cluster_backend {
    label="Backend";
    api [label="API",style=filled,fillcolor="#dbeafe",color="#2563eb",fontcolor="#172033"];
    subgraph cluster_data {
      label="Data";
      db [label="Store",shape=circle];
    }
  }
  user -> api [label="request"];
  api -> db [label="read"];
  api -> db [label="write",style=dashed];
}

digraph Named {
  node [shape=box];
  subgraph cluster_named { label="\G"; "root" [label="line\nnext"]; }
  subgraph cluster_empty { "a\nb" [label="Explicit escaped-ID label"]; }
  "a b" -> "a_u20_b";
  edge_1 -> "root";
  "__proto__" -> "constructor";
}

digraph Scopes {
  node [shape=box,label="Root default"];
  a;
  subgraph local {
    node [label="Local default"];
    b;
    a [label="Shared identity"];
  }
  c;
  edge [headport=n];
  a:e -> b:s [label="explicit endpoint beats default"];
  b -> c [label="non-ranking",constraint=0];
}

strict graph Relationships {
  node [shape=box];
  a:e -- b:w [label="first"];
  b:s -- a:n [label="latest"];
  b -- b [label="self"];
}

digraph Sets {
  node [shape=box];
  {a:n a:s b:e} -> {c c d} -> e [label="work"];
}
